import sys
import csv
import json


def main():
    path = sys.argv[1]
    totals = {}
    with open(path, 'r', encoding='utf-8', newline='') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        for row in reader:
            if len(row) < 2:
                continue
            item = row[0]
            quant = row[1]
            norm = ' '.join(item.split()).casefold()
            if not norm:
                continue
            qstr = quant.strip()
            if qstr == '':
                qty = 1
            else:
                qty = int(qstr)
                if qty < 0:
                    raise ValueError('negative quantity: %r' % quant)
            totals[norm] = totals.get(norm, 0) + qty

    result = [{'item': k, 'quantity': v} for k, v in totals.items()]
    result.sort(key=lambda x: x['item'])
    print(json.dumps(result))


if __name__ == '__main__':
    main()
